mapper.update:
update component_comment
set is_delete = #{isDelete},
    update_time = now()
where id = #{id}
  and comment_object_id = #{commentObjectId}

update component_comment
set sort = #{sort},
    update_time = now()
where id = #{id}
  and comment_object_id = #{commentObjectId}
  and is_delete = 0

update component_comment
set reply_count = greatest(reply_count + #{delta}, 0),
    update_time = now()
where id = #{id}
  and comment_object_id = #{commentObjectId}
  and is_delete = 0

update component_comment
set like_count = greatest(like_count + #{delta}, 0),
    update_time = now()
where id = #{id}
  and comment_object_id = #{commentObjectId}
  and is_delete = 0

update component_comment
set audit_status = #{auditStatus},
    update_time = now()
where id = #{id}
  and comment_object_id = #{commentObjectId}
